SELECT p.gender, p.age, a.admission_type_id, l.itemid, l.value AS troponin_t_level, COUNT(*) AS event_count, CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(*), 0) AS mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id WHERE p.gender = 'F' AND p.age BETWEEN 84 AND 94 AND a.admission_type_id = 256 AND l.itemid = 8716780 AND l.value IN (0, 1, 2) GROUP BY p.gender, p.age, a.admission_type_id, l.itemid, l.value ORDER BY p.gender, p.age, a.admission_type_id, l.itemid, l.value NULLS LAST;